import time
import pexpect
from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """A headless terminal backed by an interactive bash shell on a PTY.

    The shell sources startup files (e.g. ~/.bashrc) because it runs
    in interactive mode.  Interactive programs, modifier keys (\x03,
    \x04, etc.) all work the same way they would in a real terminal.
    """

    def __init__(self, **kwargs):
        kwargs.setdefault('encoding', 'utf-8')
        kwargs.setdefault('timeout', 30)
        self.proc = pexpect.spawn('bash', ['-i'], **kwargs)

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        self.proc.send(keystrokes)
        if wait_sec > 0:
            time.sleep(wait_sec)

    def read(self, timeout: float = 5.0) -> str:
        """Read and return the next chunk of output from the terminal."""
        return self.proc.read(timeout=timeout)

    def read_until(self, pattern, timeout: float = 30.0) -> str:
        """Read output until the given regex pattern is found."""
        self.proc.expect(pattern, timeout=timeout)
        return self.proc.before

    def close(self) -> None:
        """Terminate the shell and release the PTY."""
        if self.proc and self.proc.isalive():
            self.proc.terminate(force=True)

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass
